int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    for (int i = 0; i < H; i++) {
        scanf("%s", purple[i]);
    }

    /* Construct two 4-connected components:
       - red: top row all '#', then odd rows filled except last column,
              even rows only first column.
       - blue: bottom row all '#', then even rows filled except first column,
               odd rows only last column.
       This is a standard construction. Then add all purple cells to both.
    */
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            red[i][j] = '.';
            blue[i][j] = '.';
        }
        red[i][W] = '\0';
        blue[i][W] = '\0';
    }

    for (int j = 0; j < W; j++) {
        red[0][j] = '#';
        blue[H - 1][j] = '#';
    }

    for (int i = 1; i < H - 1; i++) {
        if (i % 2 == 1) {
            for (int j = 0; j < W - 1; j++) red[i][j] = '#';
            blue[i][W - 1] = '#';
        } else {
            red[i][0] = '#';
            for (int j = 1; j < W; j++) blue[i][j] = '#';
        }
    }

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (purple[i][j] == '#') {
