public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int H = Integer.parseInt(firstLine[0]);
        int W = Integer.parseInt(firstLine[1]);

        char[][] purple = new char[H][W];
        for (int i = 0; i < H; i++) {
            purple[i] = br.readLine().toCharArray();
        }

        // Initialize red and blue grids with '.'
        char[][] red = new char[H][W];
        char[][] blue = new char[H][W];
        for (int i = 0; i < H; i++) {
            Arrays.fill(red[i], '.');
            Arrays.fill(blue[i], '.');
        }

        // Red gets all cells where purple is present, plus extra in odd rows (or columns) to ensure connectivity
        // Blue gets all cells where purple is present, plus extra in even rows to ensure connectivity
        // This guarantees red and blue are both 4-connected and their intersection is exactly the purple cells.

        // We'll make red cover all cells in rows 0..H-2 (except last row) fully,
        // and blue cover all cells in rows 1..H-1 fully.
        // Then purple cells are set in both.
        // For cells not in both, we set only one color.

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (purple[i][j] == '#') {
                    red[i][j] = '#';
                    blue[i][j] = '#';
                }
            }
        }

        // Fill red in all cells of even rows (0-indexed) except the last row, to ensure connectivity
        for (int i = 0; i < H - 1; i += 2) {
            for (int j = 0; j < W; j++) {
                if (red[i][j] != '#') {
                    red[i][j] = '#';
                }
            }
        }
        // Also fill red in the first column of all rows to connect vertically
        for (int i = 0; i < H; i++) {
            if (red[i][0] != '#') {
                red[i][0] = '#';
            }
        }

        // Fill blue in all cells of odd rows (0-indexed) except the first row, to ensure connectivity
        for (int i = 1; i < H; i += 2) {
            for (int j = 0; j < W; j++) {
                if (blue[i][j] != '#') {
                    blue[i][j] = '#';
                }
            }
        }
        // Also fill blue in the last column of all rows to connect vertically
        for (int i = 0; i < H; i++) {
            if (blue[i][W-1] != '#') {
                blue[i][W-1] = '#';
            }
        }

        // Now we need to ensure that the intersection of red and blue is exactly the purple cells.
        // Our construction might create extra purple cells where both are '#', so we must remove those.
        // Remove red from cells that are not purple but both are '#'
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (purple[i][j] != '#' && red[i][j] == '#' && blue[i][j] == '#') {
                    // Decide which one to remove: remove red from cells that are not in a connecting path
                    // We'll remove red from these cells except if they are needed for connectivity.
                    // A simpler approach: just keep blue and remove red from such cells.
                    red[i][j] = '.';
                }
            }
        }

        // But now red might be disconnected. We need to ensure red is connected.
        // We'll add back red in a spanning tree pattern that avoids creating extra purple cells.
        // To keep it simple, we'll use a DFS/BFS to reconnect red without touching blue cells.

        // First, find a red cell to start from.
        int startR = -1, startC = -1;
        outer:
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (red[i][j] == '#') {
                    startR = i;
                    startC = j;
                    break outer;
                }
            }
        }

        // If no red cell, but purple exists, we need to create red from purple.
        if (startR == -1) {
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (purple[i][j] == '#') {
                        red[i][j] = '#';
                        startR = i;
                        startC = j;
                        break;
                    }
                }
                if (startR != -1) break;
            }
        }

        // BFS to mark visited red cells
        boolean[][] visited = new boolean[H][W];
        Queue<int[]> q = new LinkedList<>();
        if (startR != -1) {
            q.add(new int[]{startR, startC});
            visited[startR][startC] = true;
        }
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W && !visited[nr][nc] && red[nr][nc] == '#') {
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }

        // Add red cells to connect unvisited red components (but avoid making new purple)
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (red[i][j] == '#' && !visited[i][j]) {
                    // BFS from this cell to find a path to visited red, without using blue cells
                    boolean[][] localVisited = new boolean[H][W];
                    Queue<int[]> lq = new LinkedList<>();
                    lq.add(new int[]{i, j});
                    localVisited[i][j] = true;
                    int[][] parent = new int[H][W];
                    for (int[] row : parent) Arrays.fill(row, -1);
                    parent[i][j] = i * W + j;
                    boolean found = false;
                    while (!lq.isEmpty() && !found) {
                        int[] cur = lq.poll();
                        int r = cur[0], c = cur[1];
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d];
                            int nc = c + dc[d];
                            if (nr >= 0 && nr < H && nc >= 0 && nc < W && !localVisited[nr][nc]) {
                                if (blue[nr][nc] == '#') continue; // cannot use blue-only cells
                                localVisited[nr][nc] = true;
                                parent[nr][nc] = r * W + c;
                                if (visited[nr][nc]) {
                                    // Trace back and set red
                                    int cr = nr, cc = nc;
                                    while (!(cr == i && cc == j)) {
                                        if (red[cr][cc] != '#') red[cr][cc] = '#';
                                        int p = parent[cr][cc];
                                        cr = p / W;
                                        cc = p % W;
                                    }
                                    found = true;
                                    break;
                                }
                                lq.add(new int[]{nr, nc});
                            }
                        }
                    }
                    // Mark the newly connected component as visited
                    q.add(new int[]{i, j});
                    visited[i][j] = true;
                    while (!q.isEmpty()) {
                        int[] cur = q.poll();
                        int r = cur[0], c = cur[1];
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d];
                            int nc = c + dc[d];
                            if (nr >= 0 && nr < H && nc >= 0 && nc < W && !visited[nr][nc] && red[nr][nc] == '#') {
                                visited[nr][nc] = true;
                                q.add(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }

        // Output red and blue as a single grid with '#' where either red or blue is '#'
        char[][] result = new char[H][W];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (red[i][j] == '#' || blue[i][j] == '#') {
                    result[i][j] = '#';
                } else {
                    result[i][j] = '.';
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(H).append(" ").append(W).append("\n");
        for (int i = 0; i < H; i++) {
            sb.append(new String(result[i])).append("\n");
        }
        System.out.print(sb.toString());
    }
}

