        // Mark all purple cells in both
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                if (grid[i][j] == '#') {
                    red[i][j] = true;
                    blue[i][j] = true;
                }

        // For red: connect via top row (row 0)
        // For each purple cell, draw a vertical path up to row 0
        // Then connect along row 0
        int firstRedCol = -1;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == '#') {
                    // draw path upward to row 0
                    for (int r = 0; r <= i; r++) red[r][j] = true;
                    if (firstRedCol == -1) firstRedCol = j;
                    else {
                        int lo = Math.min(firstRedCol, j), hi = Math.max(firstRedCol, j);
                        for (int c = lo; c <= hi; c++) red[0][c] = true;
                    }
                }
            }
        }

        // For blue: connect via bottom row (row H-1)
        int firstBlueCol = -1;
        for (int i = 0; i < H; i++) {
