                        for (int c = lo; c <= hi; c++) blue[H-1][c] = true;
                    }
                }
            }
        }

        // Output
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < H; i++) { for (int j = 0; j < W; j++) sb.append(red[i][j] ? '#' : '.'); sb.append('\n'); }
