        for (int i = 0; i < H; i++) { for (int j = 0; j < W; j++) sb.append(blue[i][j] ? '#' : '.'); sb.append('\n'); }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] a = new char[H][];
        for (int i = 0; i < H; i++) a[i] = fs.next().toCharArray();

        char[][] red = new char[H][W];
        char[][] blue = new char[H][W];
        for (int i = 0; i < H; i++) {
            Arrays.fill(red[i], '.');
            Arrays.fill(blue[i], '.');
        }

        // Standard construction:
        // Red occupies all cells except the last column on even rows,
        // plus all purple cells.
        // Blue occupies all cells except the first column on odd rows,
        // plus all purple cells.
        //
        // This makes each of red and blue connected, and their overlap
        // is exactly the given purple cells.
        for (int i = 0; i < H; i++) {
            if (i % 2 == 0) {
                for (int j = 0; j < W - 1; j++) red[i][j] = '#';
            } else {
                for (int j = 1; j < W; j++) blue[i][j] = '#';
            }
        }

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (a[i][j] == '#') {
                    red[i][j] = '#';
                    blue[i][j] = '#';
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < H; i++) sb.append(red[i]).append('\n');
        sb.append('\n');
        for (int i = 0; i < H; i++) sb.append(blue[i]).append('\n');

        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
